import { beforeEach, describe, expect, it, vi } from "vitest";
import {
	createMcpSessionContext,
	getCurrentMcpSessionId,
	recordMcpSessionStart,
	recordMcpSessionTermination,
	recordMcpToolFailure,
	recordMcpToolInvocation,
	resolveSessionTerminationCategory,
	runWithMcpSessionContext,
} from "./mcp-session-observability.js";

const testDoubles = vi.hoisted(() => ({
	sessionStartedAdd: vi.fn(),
	sessionEndedAdd: vi.fn(),
}));

vi.mock("./metrics.js", () => ({
	sessionStarted: { add: testDoubles.sessionStartedAdd },
	sessionEnded: { add: testDoubles.sessionEndedAdd },
}));

describe("MCP session tool observations", () => {
	beforeEach(() => {
		recordMcpSessionTermination("unknown");
		vi.clearAllMocks();
	});

	it("buckets observed calls and terminates failed sessions as tool failures", () => {
		recordMcpSessionStart({
			method: "initialize",
			params: {
				protocolVersion: "2025-11-25",
				clientInfo: { name: "Claude-Desktop", version: "1.2.3" },
			},
		});

		recordMcpToolInvocation();
		recordMcpToolFailure();

		expect(resolveSessionTerminationCategory(true)).toBe("tool_failure");
		recordMcpSessionTermination("tool_failure");
		expect(testDoubles.sessionEndedAdd).toHaveBeenCalledWith(
			1,
			expect.objectContaining({
				termination_category: "tool_failure",
				tool_calls_bucket: "1",
			}),
		);
	});
	it("isolates opaque IDs across sessions and propagates the active ID", () => {
		const first = createMcpSessionContext({ method: "initialize" }, "http", {
			telemetrySessionId: "session-one",
		});
		const second = createMcpSessionContext({ method: "initialize" }, "http", {
			telemetrySessionId: "session-two",
		});

		expect(first.telemetrySessionId).not.toBe(second.telemetrySessionId);
		expect(
			runWithMcpSessionContext(first, () => getCurrentMcpSessionId()),
		).toBe("session-one");
		expect(
			runWithMcpSessionContext(second, () => getCurrentMcpSessionId()),
		).toBe("session-two");
		runWithMcpSessionContext(first, () =>
			recordMcpSessionStart({}, "http", first),
		);
		expect(testDoubles.sessionStartedAdd.mock.calls.flat()).not.toContain(
			"session-one",
		);
	});
	it("keeps telemetry session IDs out of metric attributes", () => {
		const context = createMcpSessionContext(
			{
				method: "initialize",
				params: {
					protocolVersion: "2025-11-25",
					clientInfo: { name: "Private Client", version: "1.2.3" },
				},
			},
			"http",
			{ telemetrySessionId: "session-secret" },
		);

		runWithMcpSessionContext(context, () => {
			recordMcpSessionStart({}, "http", context);
			recordMcpSessionTermination("clean", context);
		});

		expect(
			JSON.stringify([
				testDoubles.sessionStartedAdd.mock.calls,
				testDoubles.sessionEndedAdd.mock.calls,
			]),
		).not.toContain("session-secret");
	});
	it("generates one injectable opaque ID per session", () => {
		const generate = vi.fn(() => "generated-session");
		const context = createMcpSessionContext({ method: "initialize" }, "stdio", {
			generateTelemetrySessionId: generate,
		});

		expect(context.telemetrySessionId).toBe("generated-session");
		expect(generate).toHaveBeenCalledOnce();
	});
});

const USER_HASH_CONTEXT = "hevy-mcp:sentry-user-id:v1";
const USER_HASH_LENGTH = 10;
const CLOUDFLARE_COLO_PATTERN = /^[A-Z]{3}$/u;
const COUNTRY_CODE_PATTERN = /^[A-Z]{2}$/u;
const GEO_VALUE_PATTERN = /^[\p{L}\p{N}][\p{L}\p{N} .,'’()/_-]{0,63}$/u;
const IDENTIFIER_SHAPED_GEO_VALUE_PATTERN =
	/^(?:(?:\d{1,3}\.){3}\d{1,3}|-?\d+(?:\.\d+)?(?:\s*,\s*-?\d+(?:\.\d+)?)?|\d[\d -]*\d)$/u;
const MAX_GEO_VALUE_LENGTH = 64;

type RequestWithCloudflareProperties = Request & {
	readonly cf?: {
		readonly colo?: unknown;
		readonly city?: unknown;
		readonly region?: unknown;
		readonly country?: unknown;
	};
};

export interface CloudflareGeography {
	readonly localityName?: string;
	readonly localityRegion?: string;
	readonly countryCode?: string;
}

/**
 * Sanitize a Cloudflare-provided locality or region without allowing
 * identifier-shaped values such as IP addresses, coordinates, or postal codes.
 */
export function sanitizeCloudflareGeographyValue(
	value: unknown,
): string | undefined {
	if (typeof value !== "string" || value.length > MAX_GEO_VALUE_LENGTH)
		return undefined;
	const normalized = value.trim().replace(/\s+/gu, " ");
	return normalized.length <= MAX_GEO_VALUE_LENGTH &&
		!IDENTIFIER_SHAPED_GEO_VALUE_PATTERN.test(normalized) &&
		GEO_VALUE_PATTERN.test(normalized)
		? normalized
		: undefined;
}

/**
 * Return bounded Cloudflare IP-geolocation fields. These values describe the
 * request's approximate location; they are not exact location data.
 */
export function getCloudflareGeography(request: Request): CloudflareGeography {
	try {
		const cf = (request as RequestWithCloudflareProperties).cf;
		const country = cf?.country;
		const countryCode =
			typeof country === "string" && COUNTRY_CODE_PATTERN.test(country)
				? country
				: undefined;
		const localityName = sanitizeCloudflareGeographyValue(cf?.city);
		const localityRegion = sanitizeCloudflareGeographyValue(cf?.region);
		return {
			...(localityName ? { localityName } : {}),
			...(localityRegion ? { localityRegion } : {}),
			...(countryCode ? { countryCode } : {}),
		};
	} catch {
		// Request metadata is optional and must never affect MCP behavior.
		return {};
	}
}

/**
 * Return the Cloudflare edge colo only when the Worker supplied a valid value.
 * Local Requests do not have `cf`, so they deliberately produce no colo.
 */
export function getCloudflareColo(request: Request): string | undefined {
	try {
		const colo = (request as RequestWithCloudflareProperties).cf?.colo;
		return typeof colo === "string" && CLOUDFLARE_COLO_PATTERN.test(colo)
			? colo
			: undefined;
	} catch {
		// Request metadata is optional and must never affect MCP behavior.
		return undefined;
	}
}

/**
 * Derive the same short, deterministic HMAC pseudonym used by the Node
 * telemetry path without exporting or logging the caller's Hevy API key.
 */
export async function createWorkerUserHash(
	apiKey: string,
): Promise<string | undefined> {
	if (apiKey.length === 0) return undefined;
	try {
		const encoder = new TextEncoder();
		const key = await crypto.subtle.importKey(
			"raw",
			encoder.encode(apiKey),
			{ name: "HMAC", hash: "SHA-256" },
			false,
			["sign"],
		);
		const signature = await crypto.subtle.sign(
			"HMAC",
			key,
			encoder.encode(USER_HASH_CONTEXT),
		);
		return Array.from(new Uint8Array(signature), (byte) =>
			byte.toString(16).padStart(2, "0"),
		)
			.join("")
			.slice(0, USER_HASH_LENGTH);
	} catch {
		// Telemetry enrichment must never make an authenticated request fail.
		return undefined;
	}
}

