const SAFE_STACK_SOURCES = new Set([
	"error-handler",
	"hevy-client",
	"index",
	"server",
	"worker",
]);

/** Structured events emitted by the Worker adapter's private observation sink. */
export interface WorkerObservationEvent {
	readonly event: "worker.tool.invocation" | "worker.tool.completion";
	readonly name: string;
	readonly kind: "tool" | "prompt";
	readonly taxonomy?: {
		readonly feature: string;
		readonly kind: string;
		readonly operation: string;
	};
	readonly argumentKeys?: readonly string[];
	readonly argumentPresence?: Readonly<Record<string, true>>;
	readonly numericArgumentBuckets?: Readonly<Record<string, string>>;
	readonly booleanArguments?: Readonly<Record<string, boolean>>;
	readonly argumentKeyCountBucket?: string;
	readonly outcome?: SafeToolCompletion["outcome"];
	readonly durationMs?: number;
	readonly result?: WorkerResultObservation;
	readonly errorType?: string;
	readonly error?: ReturnType<typeof createSafeErrorDiagnostic>;
	readonly execution?: ReturnType<typeof createExecutionProjection>;
}

interface WorkerResultObservation {
	readonly isError: boolean;
	readonly hasStructuredContent: boolean;
	readonly contentCountBucket: string;
	readonly summary?: SafeResultSummary;
}

interface SafeResultSummary {
	readonly itemCountBucket?: string;
	readonly exerciseCountBucket?: string;
	readonly setCountBucket?: string;
	readonly workflow?: {
		readonly name: string;
		readonly pagination: Readonly<Record<string, number>>;
		readonly cacheStatus: string;
		readonly itemsScanned: number;
	};
}

export type WorkerObservationSink = (
	event: WorkerObservationEvent,
) => void | Promise<void>;

export interface WorkerTracing {
	startActiveSpan<T>(name: string, callback: (span: Span) => T): T;
}

export interface WorkerToolObserverOptions {
	/** Defaults to console.log; test callers can provide an isolated sink. */
	readonly sink?: WorkerObservationSink;
	/** HMAC pseudonym derived from the request's Hevy API key. */
	readonly userHash?: string;
	/** Cloudflare's three-letter edge colo, when the request has one. */
	readonly cloudflareColo?: string;
	/** Approximate Cloudflare IP-geolocation locality name. */
	readonly geoLocalityName?: string;
	/** Approximate Cloudflare IP-geolocation region. */
	readonly geoLocalityRegion?: string;
	/** Approximate Cloudflare IP-geolocation country code. */
	readonly geoCountryCode?: string;
	/** Injectable for unit tests; production uses Cloudflare's tracing API when available. */
	readonly tracing?: WorkerTracing;
}

function boundedString(
	value: unknown,
	maxLength = MAX_STRING_LENGTH,
): string | undefined {
	if (typeof value !== "string" || value.length === 0) return undefined;
	return value.slice(0, maxLength);
}

function safeName(value: unknown): string {
	return boundedString(value, MAX_NAME_LENGTH) ?? "unknown";
}

function safeUserHash(value: unknown): string | undefined {
	return typeof value === "string" && SAFE_USER_HASH_PATTERN.test(value)
		? value
		: undefined;
}

function safeCloudflareColo(value: unknown): string | undefined {
	return typeof value === "string" && SAFE_CLOUDFLARE_COLO_PATTERN.test(value)
		? value
		: undefined;
}

function safeCountryCode(value: unknown): string | undefined {
	return typeof value === "string" && SAFE_COUNTRY_CODE_PATTERN.test(value)
		? value
		: undefined;
}

function safeBucket(value: unknown): string | undefined {
	return typeof value === "string" && SAFE_COUNT_BUCKETS.has(value)
		? value
		: undefined;
}

function safeTaxonomy(
	invocation: SafeToolInvocation,
): WorkerObservationEvent["taxonomy"] {
	const taxonomy = invocation.taxonomy;
	if (!taxonomy) return undefined;
	const feature = boundedString(taxonomy.feature, MAX_NAME_LENGTH);
	const kind = boundedString(taxonomy.kind, MAX_NAME_LENGTH);
	const operation = boundedString(taxonomy.operation, MAX_NAME_LENGTH);
	return feature && kind && operation
		? { feature, kind, operation }
		: undefined;
}

function safeInvocation(
	invocation: SafeToolInvocation,
): Omit<WorkerObservationEvent, "event"> {
	const argumentKeys = (invocation.argumentKeys ?? [])
		.filter((key) => SAFE_ARGUMENT_KEYS.has(key))
		.slice(0, MAX_ARGUMENT_KEYS);
	const argumentPresence: Record<string, true> = {};
	for (const key of Object.keys(invocation.argumentPresence ?? {})) {
		if (SAFE_ARGUMENT_KEYS.has(key)) argumentPresence[key] = true;
	}
	const numericArgumentBuckets: Record<string, string> = {};
	for (const [key, value] of Object.entries(
		invocation.numericArgumentBuckets ?? {},
	)) {
		const bucket = safeBucket(value);
		if (SAFE_ARGUMENT_KEYS.has(key) && bucket)
			numericArgumentBuckets[key] = bucket;
	}
	const booleanArguments: Record<string, boolean> = {};
	for (const [key, value] of Object.entries(
		invocation.booleanArguments ?? {},
	)) {
		if (SAFE_ARGUMENT_KEYS.has(key) && typeof value === "boolean") {
			booleanArguments[key] = value;
		}
	}
	const keyCountBucket = safeBucket(invocation.argumentKeyCountBucket);
	return {
		name: safeName(invocation.name),
		kind: invocation.kind === "prompt" ? "prompt" : "tool",
		...(safeTaxonomy(invocation) ? { taxonomy: safeTaxonomy(invocation) } : {}),
		...(argumentKeys.length ? { argumentKeys } : {}),
		...(Object.keys(argumentPresence).length ? { argumentPresence } : {}),
		...(Object.keys(numericArgumentBuckets).length
			? { numericArgumentBuckets }
			: {}),
		...(Object.keys(booleanArguments).length ? { booleanArguments } : {}),
		...(keyCountBucket ? { argumentKeyCountBucket: keyCountBucket } : {}),
	};
}

function boundedCount(value: unknown, maximum: number): number {
	if (typeof value !== "number" || !Number.isFinite(value)) return 0;
	return Math.min(maximum, Math.max(0, Math.floor(value)));
}

function safeSummary(
	summary: ToolResultTelemetry | undefined,
): SafeResultSummary | undefined {
	if (!summary) return undefined;
	const itemCountBucket = safeBucket(summary.itemCountBucket);
	const exerciseCountBucket = safeBucket(summary.exerciseCountBucket);
	const setCountBucket = safeBucket(summary.setCountBucket);
	const workflow = summary.workflow;
	const safeWorkflow =
		workflow && SAFE_WORKFLOW_NAMES.has(workflow.name)
			? {
					name: workflow.name,
					cacheStatus: SAFE_CACHE_STATUSES.has(workflow.cacheStatus)
						? workflow.cacheStatus
						: "not-used",
					itemsScanned: boundedCount(workflow.itemsScanned, MAX_WORKFLOW_ITEMS),
					pagination: Object.fromEntries(
						Object.entries(workflow.pagination)
							.filter(([resource]) =>
								["workouts", "bodyMeasurements", "routines"].includes(resource),
							)
							.slice(0, MAX_ARGUMENT_KEYS)
							.map(([resource, pages]) => [
								resource,
								boundedCount(pages, MAX_WORKFLOW_PAGES),
							]),
					),
				}
			: undefined;
	if (
		!itemCountBucket &&
		!exerciseCountBucket &&
		!setCountBucket &&
		!safeWorkflow
	) {
		return undefined;
	}
	return {
		...(itemCountBucket ? { itemCountBucket } : {}),
		...(exerciseCountBucket ? { exerciseCountBucket } : {}),
		...(setCountBucket ? { setCountBucket } : {}),
		...(safeWorkflow ? { workflow: safeWorkflow } : {}),
	};
}

function safeResult(
	result: ToolResultObservation | undefined,
): WorkerResultObservation | undefined {
	if (!result) return undefined;
	return {
		isError: result.isError === true,
		hasStructuredContent: result.hasStructuredContent === true,
		contentCountBucket: safeBucket(result.contentCountBucket) ?? "0",
		...(safeSummary(result.summary)
			? { summary: safeSummary(result.summary) }
			: {}),
	};
}

type SafeErrorOutput = ReturnType<typeof createSafeErrorDiagnostic>;

function safeErrorStatus(value: unknown): number | undefined {
	if (typeof value !== "number") return undefined;
	return Number.isInteger(value) && value >= 100 && value <= 599
		? value
		: undefined;
}

function safeErrorMethod(value: unknown): string | undefined {
	if (typeof value !== "string") return undefined;
	const method = value.toUpperCase();
	return SAFE_HTTP_METHODS.has(method) ? method : undefined;
}

function safeErrorFrames(
	frames: SafeErrorOutput["frames"],
): SafeErrorOutput["frames"] {
	return frames
		?.filter(
			(frame) =>
				SAFE_STACK_SOURCES.has(frame.source) &&
				Number.isSafeInteger(frame.line) &&
				Number.isSafeInteger(frame.column) &&
				frame.line > 0 &&
				frame.column > 0,
		)
		.slice(0, 3);
}

function safeErrorBoolean(value: unknown): boolean | undefined {
	return typeof value === "boolean" ? value : undefined;
}

function safeError(
	error: ReturnType<typeof createSafeErrorDiagnostic> | undefined,
): ReturnType<typeof createSafeErrorDiagnostic> | undefined {
	if (!error || typeof error !== "object") return undefined;
	const category =
		allowedValue<SafeErrorOutput["category"]>(
			error.category,
			SAFE_ERROR_CATEGORIES,
		) ?? "UnknownError";
	const code = allowedValue<string>(error.code, SAFE_ERROR_CODES);
	const method = safeErrorMethod(error.method);
	const endpoint = allowedValue<string>(error.endpoint, SAFE_ENDPOINTS);
	const frames = safeErrorFrames(error.frames);
	const phase = allowedValue<NonNullable<SafeErrorOutput["phase"]>>(
		error.phase,
		SAFE_REQUEST_PHASES,
	);
	const operationSafety = allowedValue<
		NonNullable<SafeErrorOutput["operation_safety"]>
	>(error.operation_safety, SAFE_OPERATION_SAFETY);
	const commitState = allowedValue<
		NonNullable<SafeErrorOutput["commit_state"]>
	>(error.commit_state, SAFE_COMMIT_STATES);
	const outcome = allowedValue<NonNullable<SafeErrorOutput["outcome"]>>(
		error.outcome,
		SAFE_EXECUTION_OUTCOMES,
	);
	const status = safeErrorStatus(error.status);
	const safeToRetry = safeErrorBoolean(error.safe_to_retry);
	const sanitized: SafeErrorOutput = { category };
	if (code !== undefined) sanitized.code = code;
	if (status !== undefined) sanitized.status = status;
	if (method !== undefined) sanitized.method = method;
	if (endpoint !== undefined) sanitized.endpoint = endpoint;
	if (frames?.length) sanitized.frames = frames;
	if (phase !== undefined) sanitized.phase = phase;
	if (operationSafety !== undefined)
		sanitized.operation_safety = operationSafety;
	if (commitState !== undefined) sanitized.commit_state = commitState;
	if (safeToRetry !== undefined) sanitized.safe_to_retry = safeToRetry;
	if (outcome !== undefined) sanitized.outcome = outcome;
	return sanitized;
}

type SafeExecutionSource = Partial<
	Pick<
		StructuredExecutionProjection,
		| "outcome"
		| "phase"
		| "operation_safety"
		| "commit_state"
		| "safe_to_retry"
		| "code"
		| "status"
	>
>;

function allowedValue<T extends string>(
	value: unknown,
	allowed: ReadonlySet<string>,
): T | undefined {
	return typeof value === "string" && allowed.has(value)
		? (value as T)
		: undefined;
}

function safeExecution(
	source: SafeExecutionSource | undefined,
): ReturnType<typeof createExecutionProjection> | undefined {
	if (!source) return undefined;
	return createExecutionProjection({
		outcome: allowedValue(source.outcome, SAFE_EXECUTION_OUTCOMES),
		phase: allowedValue(source.phase, SAFE_REQUEST_PHASES),
		operation_safety: allowedValue(
			source.operation_safety,
			SAFE_OPERATION_SAFETY,
		),
		commit_state: allowedValue(source.commit_state, SAFE_COMMIT_STATES),
		safe_to_retry:
			typeof source.safe_to_retry === "boolean"
				? source.safe_to_retry
				: undefined,
		code:
			typeof source.code === "string" && SAFE_ERROR_CODES.has(source.code)
				? source.code
				: undefined,
		status:
			typeof source.status === "number" &&
			Number.isInteger(source.status) &&
			source.status >= 100 &&
			source.status <= 599
				? source.status
				: undefined,
	});
}

function emitBestEffort(
	sink: WorkerObservationSink,
	event: WorkerObservationEvent,
): void {
	try {
		const pending = sink(event);
		if (pending) Promise.resolve(pending).catch(() => undefined);
	} catch {
		// Worker observation is strictly best effort and must not affect MCP behavior.
	}
}

function setSpanAttributes(
	span: Span,
	attributes: Readonly<Record<string, string | number | boolean>>,
): void {
	for (const [key, value] of Object.entries(attributes)) {
		try {
			span.setAttribute(key, value);
		} catch {
			// Trace enrichment must never affect MCP behavior.
		}
	}
}

function finishSpan(
	span: Span,
	kind: WorkerObservationEvent["kind"],
	outcome: SafeToolCompletion["outcome"],
): void {
	try {
		span.setAttribute(
			kind === "prompt" ? "mcp.prompt.outcome" : "mcp.tool.outcome",
			outcome,
		);
	} catch {
		// Trace enrichment must never affect MCP behavior.
	}
	try {
		span.end();
	} catch {
		// Trace enrichment must never affect MCP behavior.
	}
}

/** Worker-only adapter for Core's privacy-safe semantic observation contract. */
export function createWorkerToolObserver(
	options: WorkerToolObserverOptions = {},
): ToolObserver {
	const sink =
		options.sink ?? ((event: WorkerObservationEvent) => console.log(event));
	const workerTracing: WorkerTracing | undefined =
		options.tracing ?? cloudflareWorkers.tracing;
	const userHash = safeUserHash(options.userHash);
	const cloudflareColo = safeCloudflareColo(options.cloudflareColo);
	const geoLocalityName = sanitizeCloudflareGeographyValue(
		options.geoLocalityName,
	);
	const geoLocalityRegion = sanitizeCloudflareGeographyValue(
		options.geoLocalityRegion,
	);
	const geoCountryCode = safeCountryCode(options.geoCountryCode);
	return {
		start(invocation): ToolObservationScope {
			let safe: Omit<WorkerObservationEvent, "event">;
			try {
				safe = safeInvocation(invocation);
			} catch {
				safe = { name: "unknown", kind: "tool" };
			}
			const startedAt = Date.now();
			emitBestEffort(sink, { event: "worker.tool.invocation", ...safe });
			let finished = false;
			let activeSpan: Span | undefined;
			return {
				run<T>(operation: () => Promise<T>): Promise<T> {
					if (activeSpan || !workerTracing?.startActiveSpan) return operation();
					let callbackEntered = false;
					try {
						return workerTracing.startActiveSpan(
							`mcp.${safe.kind}.${safe.name}`,
							(span) => {
								callbackEntered = true;
								activeSpan = span;
								setSpanAttributes(span, {
									"mcp.span.category": safe.kind,
									"mcp.operation.kind": safe.kind,
									[safe.kind === "prompt"
										? "mcp.prompt.name"
										: "mcp.tool.name"]: safe.name,
									...(safe.taxonomy
										? {
												"hevy.feature": safe.taxonomy.feature,
												"mcp.tool.kind": safe.taxonomy.kind,
												"mcp.tool.operation": safe.taxonomy.operation,
											}
										: {}),
									...(userHash ? { "user.hash": userHash } : {}),
									...(cloudflareColo
										? { "cloudflare.colo": cloudflareColo }
										: {}),
									...(geoLocalityName
										? { "geo.locality.name": geoLocalityName }
										: {}),
									...(geoLocalityRegion
										? { "geo.locality.region": geoLocalityRegion }
										: {}),
									...(geoCountryCode
										? { "geo.country.code": geoCountryCode }
										: {}),
								});
								return operation();
							},
						);
					} catch (error) {
						// If the callback ran, its error belongs to the operation and the
						// core runtime will call finish. Only bypass a failed tracing API
						// before callback entry.
						if (callbackEntered) throw error;
						return operation();
					}
				},
				finish(completion) {
					if (finished) return;
					finished = true;
					if (activeSpan) {
						finishSpan(activeSpan, safe.kind, completion.outcome);
						activeSpan = undefined;
					}
					try {
						const durationMs = boundedCount(
							completion.durationMs || Date.now() - startedAt,
							Number.MAX_SAFE_INTEGER,
						);
						const error = safeError(completion.error);
						const execution = completion.errorOutcome
							? safeExecution(completion.errorOutcome)
							: safeExecution(error);
						const result = safeResult(completion.result);
						emitBestEffort(sink, {
							event: "worker.tool.completion",
							...safe,
							outcome: completion.outcome,
							durationMs,
							...(result ? { result } : {}),
							...(SAFE_ERROR_TYPES.has(completion.errorType ?? "")
								? { errorType: completion.errorType }
								: {}),
							...(error ? { error } : {}),
							...(execution ? { execution } : {}),
						});
					} catch {
						// Observation projection is best effort and must not affect MCP behavior.
					}
				},
			};
		},
	};
}

import { describe, expect, it } from "vitest";
import {
	createWorkerUserHash,
	getCloudflareColo,
	getCloudflareGeography,
} from "./worker-telemetry.js";

describe("Worker telemetry context", () => {
	it("keeps the existing deterministic HMAC user pseudonym", async () => {
		await expect(createWorkerUserHash("test-key")).resolves.toBe("2cb0b5f95a");
		await expect(createWorkerUserHash("another-key")).resolves.toBe(
			"0ddf86a356",
		);
		await expect(createWorkerUserHash("test-key")).resolves.not.toBe(
			"another-key",
		);
	});

	it("does not derive a hash for an empty credential", async () => {
		await expect(createWorkerUserHash("")).resolves.toBeUndefined();
	});

	it("returns only a valid Cloudflare colo from request metadata", () => {
		const request = new Request("https://worker.example/mcp");
		Object.defineProperty(request, "cf", {
			value: { colo: "SFO", clientIp: "198.51.100.10" },
		});
		expect(getCloudflareColo(request)).toBe("SFO");
		expect(JSON.stringify(getCloudflareColo(request))).not.toContain(
			"198.51.100.10",
		);
	});

	it("returns bounded approximate geography without client identifiers", () => {
		const request = new Request("https://worker.example/mcp");
		Object.defineProperty(request, "cf", {
			value: {
				city: "San Francisco",
				region: "California",
				country: "US",
				clientIp: "198.51.100.10",
			},
		});
		expect(getCloudflareGeography(request)).toEqual({
			localityName: "San Francisco",
			localityRegion: "California",
			countryCode: "US",
		});
		expect(JSON.stringify(getCloudflareGeography(request))).not.toContain(
			"198.51.100.10",
		);
	});

	it("reads each geography field once", () => {
		const reads = { city: 0, region: 0, country: 0 };
		const cf = {
			get city() {
				reads.city += 1;
				return "San Francisco";
			},
			get region() {
				reads.region += 1;
				return "California";
			},
			get country() {
				reads.country += 1;
				return "US";
			},
		};
		const request = new Request("https://worker.example/mcp");
		Object.defineProperty(request, "cf", { value: cf });

		expect(getCloudflareGeography(request)).toEqual({
			localityName: "San Francisco",
			localityRegion: "California",
			countryCode: "US",
		});
		expect(reads).toEqual({ city: 1, region: 1, country: 1 });
	});

	it.each([
		{ city: "", region: "California", country: "US" },
		{ city: "San Francisco", region: "California", country: "USA" },
		{ city: "<script>", region: "California", country: "US" },
	])("drops malformed geography fields: %j", (cf) => {
		const request = new Request("https://worker.example/mcp");
		Object.defineProperty(request, "cf", { value: cf });
		expect(getCloudflareGeography(request)).toEqual(
			cf.country === "USA"
				? { localityName: "San Francisco", localityRegion: "California" }
				: { localityRegion: "California", countryCode: "US" },
		);
	});

	it.each([
		"198.51.100.10",
		"37.7749",
		"37.7749, -122.4194",
		"94103",
		"12345-6789",
		"a".repeat(65),
	])("rejects identifier-shaped or oversized geography values: %s", (value) => {
		const request = new Request("https://worker.example/mcp");
		Object.defineProperty(request, "cf", {
			value: { city: value, region: value, country: "US" },
		});
		expect(getCloudflareGeography(request)).toEqual({ countryCode: "US" });
	});

	it.each([
		undefined,
		{},
		{ colo: "sfo" },
		{ colo: "UNKNOWN" },
		{ colo: "1.2.3" },
		{ colo: "" },
	])("omits a missing or invalid colo: %j", (cf) => {
		const request = new Request("https://worker.example/mcp");
		if (cf !== undefined) Object.defineProperty(request, "cf", { value: cf });
		expect(getCloudflareColo(request)).toBeUndefined();
	});
});

// Telemetry must be initialized before any other imports so that
// OpenTelemetry and Sentry are ready before application code runs.
import { tracer, serviceName, serviceVersion } from "./utils/telemetry.js";
import { StdioServerTransport } from "@modelcontextprotocol/server/stdio";
import { SpanStatusCode } from "@opentelemetry/api";
import { z } from "zod";
import { createHevyMcpServer, mergeAbortSignals } from "@hevy-mcp/core";
import { createHevyClient, isHevyHttpError } from "@hevy-mcp/hevy-client";
import { assertApiKey, parseConfig } from "./utils/config.js";
import { parseNodeCliOptions, type NodeTransport } from "./utils/arguments.js";
import { startStreamableHttpServer } from "./utils/streamable-http.js";
import {
	createNodeCacheObserver,
	createNodeHevyClientOptions,
} from "./utils/hevy-client-observability.js";
import { createNodeToolObserver } from "./utils/tool-observer.js";
import { createInstrumentedStdioTransport } from "./utils/stdio-observability.js";
import {
	recordMcpSessionTermination,
	resolveSessionTerminationCategory,
} from "./utils/mcp-session-observability.js";
import { installSdkErrorTracking } from "./utils/sdk-observability.js";
import {
	INVALID_API_KEY_MESSAGE,
	recordLifecycleFailure,
	runNodeLifecycle,
} from "./utils/node-lifecycle.js";

const name = serviceName;
const version = serviceVersion;

const HELP_TEXT = [
	"Usage:",
	"  hevy-mcp [options]",
	"",
	"Options:",
	"  -h, --help                 Show this help message and exit",
	"  -v, --version              Show version and exit",
	"  --transport stdio|http     Select the transport (default: stdio)",
	"  --host <host>              HTTP bind host (default: 127.0.0.1)",
	"  --port <port>              HTTP bind port (default: 3000)",
	"",
	"Environment:",
	"  HEVY_API_KEY=<api-key>     Hevy API key from Hevy app settings",
	"  HEVY_MCP_DEBUG=1           Enable verbose diagnostics on stderr",
	"  HEVY_MCP_HTTP_BEARER_TOKEN Protect non-loopback HTTP deployments",
	"  HEVY_MCP_TELEMETRY=0     Disable all project telemetry",
	"  HEVY_MCP_TELEMETRY_DIAGNOSTICS=0  Suppress exception details",
	"",
	"Examples:",
	"  HEVY_API_KEY=your-key npx hevy-mcp",
	"  HEVY_API_KEY=your-key npx hevy-mcp --transport http --port 3000",
].join("\n");

function getCliAction(args: string[]): "start" | "version" | "help" {
	for (const arg of args) {
		if (arg === "--version" || arg === "-v") {
			return "version";
		}

		if (arg === "--help" || arg === "-h") {
			return "help";
		}
	}

	return "start";
}

const HEVY_API_BASEURL = "https://api.hevyapp.com";
const STARTUP_PROBE_TIMEOUT_MS = 5_000;

const API_KEY_VALIDATION_WARNING =
	"Warning: HEVY_API_KEY could not be validated during startup. Startup will continue; check your network connection and Hevy API availability.";
const SAFE_NETWORK_ERROR_CODES = new Set([
	"EAI_AGAIN",
	"ECONNABORTED",
	"ECONNREFUSED",
	"ECONNRESET",
	"ENETUNREACH",
	"ENOTFOUND",
	"ERR_NETWORK",
	"ERR_SOCKET_TIMEOUT",
	"ETIMEDOUT",
	"HEVY_RETRY_EXHAUSTED",
]);

const serverConfigSchema = z.object({
	apiKey: z
		.string()
		.min(1, "Hevy API key is required")
		.describe("Your Hevy API key (available in the Hevy app settings)."),
});

function getHttpStatus(error: unknown): number | undefined {
	if (isHevyHttpError(error)) {
		return error.status;
	}
	if (!error || typeof error !== "object" || !("response" in error)) {
		return undefined;
	}

	const response = error.response;
	if (!response || typeof response !== "object" || !("status" in response)) {
		return undefined;
	}

	return typeof response.status === "number" &&
		Number.isInteger(response.status) &&
		response.status >= 100 &&
		response.status <= 599
		? response.status
		: undefined;
}

function getSafeValidationDiagnostic(error: unknown): string | undefined {
	const status = getHttpStatus(error);
	if (status !== undefined) {
		return `HTTP ${status}`;
	}

	if (!error || typeof error !== "object" || !("code" in error)) {
		return undefined;
	}

	const code = error.code;
	return typeof code === "string" && SAFE_NETWORK_ERROR_CODES.has(code)
		? code
		: undefined;
}
async function validateApiKey(apiKey: string, signal?: AbortSignal) {
	// Keep the startup probe separate from the normal MCP-aware client. The
	// server is not connected yet, so structured client logging is intentionally
	// omitted until the normal client is built below.
	const startupProbeClient = createHevyClient({
		apiKey,
		baseUrl: HEVY_API_BASEURL,
		maxGetRetries: 0,
		timeoutMs: STARTUP_PROBE_TIMEOUT_MS,
	});

	try {
		await startupProbeClient.getUserInfo({
			signal,
			deadline: Date.now() + STARTUP_PROBE_TIMEOUT_MS,
		});
	} catch (error) {
		if (signal?.aborted) throw error;
		const status = getHttpStatus(error);
		if (status === 401 || status === 403) {
			throw new Error(INVALID_API_KEY_MESSAGE);
		}

		const diagnostic = getSafeValidationDiagnostic(error);
		console.error(
			diagnostic
				? `${API_KEY_VALIDATION_WARNING} Diagnostic: ${diagnostic}.`
				: API_KEY_VALIDATION_WARNING,
		);
	}
}

function buildServer(
	apiKey: string,
	transport: NodeTransport = "stdio",
	lifecycleSignal?: AbortSignal,
) {
	return tracer.startActiveSpan(
		"mcp.server.build",
		{
			attributes: {
				"mcp.span.category": "startup",
				"mcp.server.name": name,
				"mcp.server.version": version,
				"mcp.transport": transport,
			},
		},
		(span) => {
			try {
				const server = createHevyMcpServer({
					createClient: ({ onLog }) =>
						createHevyClient({
							apiKey,
							...createNodeHevyClientOptions(),
							onLog,
						}),
					lifecycleSignal,
					onToolsRegistered: (count) =>
						span.setAttribute("mcp.tools.count", count),
					observer: createNodeToolObserver(),
					cacheObserver: createNodeCacheObserver(),
				});
				installSdkErrorTracking(server, transport);
				console.error("Hevy client initialized with API key");

				span.setStatus({ code: SpanStatusCode.OK });
				return server;
			} catch (e) {
				recordLifecycleFailure(span, e, "build", "startup_failure");
				span.setStatus({ code: SpanStatusCode.ERROR });
				throw e;
			} finally {
				span.end();
			}
		},
	);
}

export async function createNodeMcpServer(
	{ apiKey }: { apiKey: string },
	transport: NodeTransport = "stdio",
	lifecycleSignal?: AbortSignal,
) {
	const { apiKey: validatedApiKey } = serverConfigSchema.parse({ apiKey });
	await validateApiKey(validatedApiKey, lifecycleSignal);
	return buildServer(validatedApiKey, transport, lifecycleSignal);
}

export async function runStdioServer() {
	const args = process.argv.slice(2);
	const cliAction = getCliAction(args);

	if (cliAction === "version") {
		console.error(`${name} v${version}`);
		return;
	}
	if (cliAction === "help") {
		console.log(HELP_TEXT);
		return;
	}

	await runNodeLifecycle({
		transport: "stdio",
		start: async (context) => {
			const { signal } = context;
			const cfg = parseConfig(process.env);
			const apiKey = cfg.apiKey;
			assertApiKey(apiKey);
			const server = await createNodeMcpServer({ apiKey }, "stdio", signal);
			console.error("Starting MCP server in stdio mode");
			const transport = createInstrumentedStdioTransport(
				new StdioServerTransport(),
			);
			context.markConnectAttempted();
			await tracer.startActiveSpan(
				"mcp.server.connect",
				{
					attributes: {
						"mcp.span.category": "session",
						"mcp.transport": "stdio",
					},
				},
				async (connectSpan) => {
					try {
						await server.connect(transport);
						context.markConnectSucceeded();
						connectSpan.setStatus({ code: SpanStatusCode.OK });
					} catch (error) {
						recordLifecycleFailure(
							connectSpan,
							error,
							"connect",
							"connect_failure",
						);
						connectSpan.setStatus({ code: SpanStatusCode.ERROR });
						throw error;
					} finally {
						connectSpan.end();
					}
				},
			);
			return {
				target: server,
				onShutdown: (succeeded) =>
					recordMcpSessionTermination(
						resolveSessionTerminationCategory(succeeded),
					),
			};
		},
		onFailure: (reason, outcome) => {
			if (outcome.transport === "stdio") {
				recordMcpSessionTermination(reason);
			}
		},
	});
}

export async function runServer(): Promise<void> {
	const args = process.argv.slice(2);
	const cliAction = getCliAction(args);
	if (cliAction === "version") {
		console.error(`${name} v${version}`);
		return;
	}
	if (cliAction === "help") {
		console.log(HELP_TEXT);
		return;
	}

	const options = parseNodeCliOptions(args);
	if (options.transport === "stdio") {
		await runStdioServer();
		return;
	}

	await runNodeLifecycle({
		transport: "http",
		start: async (context) => {
			const { signal } = context;
			const cfg = parseConfig(process.env);
			assertApiKey(cfg.apiKey);
			await validateApiKey(cfg.apiKey, signal);
			const handle = await startStreamableHttpServer(
				options,
				cfg.apiKey,
				(params) =>
					Promise.resolve(
						buildServer(
							params.apiKey,
							"http",
							mergeAbortSignals(signal, params.lifecycleSignal),
						),
					),
			);
			context.markListening();
			console.error(
				`Starting MCP server in HTTP mode at ${options.host}:${options.port}/mcp`,
			);
			return { target: handle };
		},
		onFailure: (_reason, outcome) => {
			if (outcome.transport === "http") {
				recordMcpSessionTermination(
					outcome.listening ? "unknown" : "startup_failure",
				);
			}
		},
	});
}

import { createHevyMcpServer } from "@hevy-mcp/core";
import { createHevyClient } from "@hevy-mcp/hevy-client";
import { z } from "zod";
import type { NodeTransport } from "./utils/arguments.js";

const serverConfigSchema = z.object({
	apiKey: z
		.string()
		.min(1, "Hevy API key is required")
		.describe("Your Hevy API key (available in the Hevy app settings)."),
});

/**
 * Create an unconnected MCP server for embedding in a Node application.
 *
 * This entry point intentionally contains no Node runtime bootstrap. It does
 * not read process state, probe Hevy, install process handlers, initialize
 * telemetry, or connect a transport. The embedding application owns those
 * concerns and the transport lifecycle.
 */
export function createNodeMcpServer(
	{ apiKey }: { apiKey: string },
	_transport: NodeTransport = "stdio",
	lifecycleSignal?: AbortSignal,
) {
	try {
		const { apiKey: validatedApiKey } = serverConfigSchema.parse({ apiKey });
		return Promise.resolve(
			createHevyMcpServer({
				createClient: ({ onLog }) =>
					createHevyClient({
						apiKey: validatedApiKey,
						onLog,
					}),
				lifecycleSignal,
			}),
		);
	} catch (error) {
		return Promise.reject(error);
	}
}

/**
 * Compatibility wrapper for the executable runtime. Importing this module
 * does not evaluate the runtime bootstrap; it is loaded only when invoked.
 */
export async function runStdioServer(): Promise<void> {
	const { runStdioServer: run } = await import("./runtime.js");
	return run();
}

/**
 * Compatibility wrapper for the executable runtime. Importing this module
 * does not evaluate the runtime bootstrap; it is loaded only when invoked.
 */
export async function runServer(): Promise<void> {
	const { runServer: run } = await import("./runtime.js");
	return run();
}

